validate=r'''#!/usr/bin/env node
import assert from'node:assert/strict';import fs from'node:fs';import path from'node:path';import{fileURLToPath}from'node:url';import{dimensions,manifest,registry,ledger,report,html}from'./build-counter-selector-wave-08.mjs';const R=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),J=p=>JSON.parse(fs.readFileSync(path.join(R,p),'utf8')),T=p=>fs.readFileSync(path.join(R,p),'utf8');
export function check(c,parent,r,l){assert.deepEqual(r.counts,c.expected_counts);assert.equal(r.records.length,4);assert.equal(l.records.length,4);assert.equal(l.counts.resolved_by_averaging,0);let parentBy=Object.fromEntries(parent.packets.map(x=>[x.packet_id,x]));let by=Object.fromEntries(r.records.map(x=>[x.packet_id,x]));assert.deepEqual(Object.keys(by).sort(),['CS-BLIND-0012-B02','CS-BLIND-0017-B02','CS-BLIND-0022-B02','CS-BLIND-0027-B02']);assert.equal(r.records.reduce((n,x)=>n+x.review_passes.length,0),8);assert.equal(r.records.reduce((n,x)=>n+x.bounded_support_count,0),4);assert.equal(r.records.filter(x=>x.bounded_support_count>0).length,2);assert.equal(r.records.filter(x=>x.mechanism_observations).length,2);assert.equal(r.records.filter(x=>x.analysis_class_recommendation).length,3);for(let x of r.records){assert.ok(parentBy[x.packet_id]);assert.equal(x.parent_attribution_class,parentBy[x.packet_id].attribution_class);assert.deepEqual(Object.keys(x.dimension_vector),dimensions);assert.equal(x.review_passes.length,2);for(let p of x.review_passes){assert.equal(p.fresh_identity_minimized_context,true);assert.equal(p.external_independence_claimed,false)}assert.equal(x.field_test_eligible,false);assert.equal(x.operator_finding,false);assert.equal(x.promotion_generated,false);assert.equal(x.person_ranking_generated,false);assert.equal(x.public_identity_release_authorized,false);assert.equal(x.graph_effect,'none')}let raw=JSON.stringify(r.records);for(let forbidden of ['candidate_id','public_label','denominator_class','source_id'])assert.equal(raw.includes(forbidden),false);assert.equal(by['CS-BLIND-0012-B02'].bounded_support_count,2);assert.equal(by['CS-BLIND-0012-B02'].dimension_vector.exception_handling,'bounded_support_collective_evidence_channel_request');assert.equal(by['CS-BLIND-0012-B02'].dimension_vector.epistemic_restraint,'bounded_support_collective_uncertainty_preserved');assert.equal(by['CS-BLIND-0017-B02'].bounded_support_count,2);assert.equal(by['CS-BLIND-0017-B02'].dimension_vector.custody,'bounded_support_checking_output_issued_and_preserved');assert.equal(by['CS-BLIND-0017-B02'].dimension_vector.governed_capacity,'bounded_support_independent_checking_function_exercised');for(let id of ['CS-BLIND-0022-B02','CS-BLIND-0027-B02']){assert.equal(by[id].bounded_support_count,0);assert.ok(Object.values(by[id].dimension_vector).every(v=>v==='not_attributable_from_system_mechanism'));assert.equal(by[id].mechanism_observations.partnership_capacity_established,false)}for(let x of r.records.filter(x=>x.analysis_class_recommendation))assert.equal(x.analysis_class_recommendation.historical_row_rewritten,false);for(let k of ['procedural_separation_is_external_independence','collective_packet_is_individual_operator_finding','catastrophic_consequence_proves_counterfactual_efficacy','checking_output_is_support_adjusted_surplus','system_mechanism_is_person_or_partnership','record_correction_is_relationship_repair','reform_announcement_is_durable_repair','bounded_dimension_support_is_operator_finding','review_result_authorizes_field_test'])assert.equal(c.boundaries[k],false);assert.equal(c.boundaries.graph_effect,'none');return true}
export function validate(){let c=J('data/project/counter-selector-wave-08-blind-review.json'),p=J(c.parent_packet_registry_path),pm=J(c.parent_release_path),r=J('data/project/counter-selector-blind-review-b02-registry.json'),l=J('data/project/counter-selector-review-disagreement-b02-ledger.json'),m=J('data/project/counter-selector-wave-08-release-manifest.json'),q=J('reports/core-thesis/counter-selector-wave-08/data.json'),h=T('reports/core-thesis/counter-selector-wave-08/index.html');check(c,p,r,l);assert.deepEqual(r,registry(c,p,pm));assert.deepEqual(l,ledger(c,r));assert.deepEqual(m,manifest());assert.deepEqual(q,report(c,r,l,m));assert.equal(h,html(q));assert.equal(m.entries.length,8);assert.equal(q.counts.adversarial_mutations,32);assert.ok(h.includes('4 PACKETS · 8 PASSES · 4 BOUNDED SUPPORTS · 0 FIELD TESTS'));console.log('validate-wave08 PASS',m.combined_sha256)}if(process.argv[1]===fileURLToPath(import.meta.url))validate();
'''
W('tools/validate-counter-selector-wave-08.mjs',validate)
